function modal(title,body,onSubmit){dialog.innerHTML=`<form><div class="dialog-head"><h2>${esc(title)}</h2><button type="button" data-close aria-label="Close">×</button></div>${body}<p class="modal-error" role="alert"></p><div class="dialog-actions"><button type="button" data-close class="secondary-button">Cancel</button><button class="button" type="submit">Confirm</button></div></form>`;dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await onSubmit(new FormData(e.target));dialog.close();}catch(err){dialog.querySelector('.modal-error').textContent=err.message;b.disabled=false;}};dialog.showModal();dialog.querySelector('input,select')?.focus();}
const sectionFor=type=>items.find(d=>d.canvasType===type);
const sections=()=>items.filter(d=>d.canvasType);
function url(mode,id){return `#world/${encodeURIComponent(reality.id)}/${mode}${id?'/'+encodeURIComponent(id):''}`;}
