function remember(){const ed=area.querySelector('#document-body');if(current&&ed){const selection=window.getSelection();let caret=null;if(selection.rangeCount&&ed.contains(selection.anchorNode)){const range=selection.getRangeAt(0).cloneRange();range.selectNodeContents(ed);range.setEnd(selection.anchorNode,selection.anchorOffset);caret=range.toString().length;}positions.set(current.id,{scroll:area.querySelector('.document-scroll').scrollTop,caret});}}
function sanitize(html){return window.DaydreamFormat.sanitize(html);}
async function flush(){clearTimeout(timer);if(!dirty)return saveChain.then(()=>true);const body=area.querySelector('#document-body'),title=area.querySelector('#document-title');if(!current||!body)return true;const revision=epoch,draft={...current,name:title.value.trim()||`Untitled ${TYPES[current.type]}`,number:area.querySelector('#chapter-number')?.value?Number(area.querySelector('#chapter-number').value):current.type==='chapter'&&!current.canvasType?null:current.number,html:sanitize(body.innerHTML)};notify('Saving…');saveChain=saveChain.catch(()=>{}).then(async()=>{if(!draft.isDraft)return repo.saveDocument(draft);const existing=createdDrafts.get(draft.id);if(existing)return repo.saveDocument({...draft,id:existing,isDraft:false});const saved=await repo.createDocument(draft.realityId,draft);createdDrafts.set(draft.id,saved.id);return saved;});try{const saved=await saveChain;if(current?.id===draft.id||current?.id===saved.id){const firstSave=current.isDraft;current={...current,...saved,isDraft:false};const idx=items.findIndex(d=>d.id===saved.id);if(idx>=0)items[idx]=window.DaydreamDB.metadata(saved);else items.push(window.DaydreamDB.metadata(saved));if(firstSave){if(location.hash===activeHash){activeHash=url('doc',saved.id);history.replaceState(null,'',activeHash);window.DaydreamAuth?.remember(activeHash);}await refresh();const side=area.querySelector('.writer-sidebar'),tmp=document.createElement('div');tmp.innerHTML=sidebar();side?.replaceWith(tmp.firstElementChild);}if(epoch===revision){dirty=false;notify(repo.status?.()||'Saved on this device');}else notify('Unsaved changes');}return true;}catch(error){dirty=true;notify(`Not saved: ${error.message}`,true);return false;}}
