async function beforeNavigate(){if(window.DaydreamNodeCanvas.beforeNavigate&&!await window.DaydreamNodeCanvas.beforeNavigate()){history.replaceState(null,'',activeHash);return false;}remember();const okay=await flush();if(!okay)history.replaceState(null,'',activeHash);return okay;}
