function shell(main,mode){area.innerHTML=`<div class="writer-shell ${mode==='canvas'?'canvas-mode':'reading-mode'} ${sidebarHidden?'sidebar-collapsed':''} ${window.matchMedia?.('(max-width:760px)').matches&&!sidebarHidden?'sidebar-mobile-open':''}"><header class="writer-header"><a href="#home" class="writer-brand" aria-label="Daydream home"><span class="brand-mark">d.</span><span class="brand-name">daydream</span></a><span class="reality-label">${esc(reality?.name||'Your alternative realities')}</span><div class="writer-actions">${reality?`<button data-work="canvas" class="${mode==='canvas'?'active':''}">Canvas</button><button data-work="library" class="${mode==='library'?'active':''}">Library</button><button data-work="add" ${sections().length===Object.keys(TYPES).length?'disabled':''}>Add section</button><a href="#workspace" class="all-worlds-link">All Worlds</a>`:''}<a href="#capture">Dream Capture</a><button data-pause class="pause-compact">Pause</button><button class="tutorial-help" data-tutorial-open aria-label="Open workspace tutorial" title="Workspace tutorial">?</button><button class="account-button" data-account-open>Account</button><button class="account-button" data-auth-logout>Log Out</button></div></header>${reality?sidebar()+`<button class="sidebar-edge-toggle" data-work="sidebar" aria-controls="document-sidebar" aria-expanded="${!sidebarHidden}" aria-label="Expand sidebar" ${sidebarHidden?'':'hidden'}>›</button>`:''}<div class="writer-main">${main}</div><div class="writer-footer"><span id="work-status" role="status" aria-live="polite">${dirty?'Unsaved changes':esc(repo.status?.()||'Saved on this device')}</span><span>${repo.isAccount?'Account storage · keep exports as backups':'Device-local storage · export a copy to keep elsewhere'}</span>${undoId?'<button data-work="undo">Undo deletion</button>':''}</div></div>`;}
function sidebar(){const hubs=sections(),counts=new Map();for(const d of items)if(!d.canvasType)counts.set(d.type,(counts.get(d.type)||0)+1);return `<aside id="document-sidebar" class="writer-sidebar" aria-label="Sections"><div class="sidebar-heading"><span>Your sections</span><button data-work="collapse-sidebar" aria-label="Collapse sidebar">‹</button></div><div class="sidebar-tree">${hubs.map(d=>`<div class="tree-row"><button class="tree-name ${group===d.id||current?.type===d.type?'active':''}" data-library="${esc(d.id)}"><span>${esc(d.name)}</span><small>${counts.get(d.type)||0}</small></button></div>`).join('')||'<p class="sidebar-empty">Your sections will appear here.</p>'}</div></aside>`;}

async function overview(){activeHash=location.hash;reality=null;current=null;view='overview';window.DaydreamNodeCanvas.dispose();const worlds=await repo.all('realities');shell(`<div class="overview-greeting">${esc(window.DaydreamExperience?.greeting()||'Welcome back.')}</div><div id="reality-canvas" class="full-canvas"></div><button class="overview-create" data-work="create-reality">+ Create a reality</button>`,'canvas');const nodes=worlds.length?worlds.map((r,i)=>({id:r.id,name:r.name,type:'world',subtitle:'ALTERNATIVE REALITY',text:r.description||'',editable:true,updatedAt:r.updatedAt,x:r.overviewX??380+(i%3)*340,y:r.overviewY??200+Math.floor(i/3)*220})):[{id:'create',name:'Create your alternative reality',type:'create-world',subtitle:'BEGIN HERE',text:'Give your first imagined world a name.',x:440,y:260}];canvas=window.DaydreamNodeCanvas.mount(area.querySelector('#reality-canvas'),'realities-v2',{nodes,edges:[]},{label:'Alternative realities canvas',onOpen:n=>{if(n.id==='create')createReality();else location.hash=`#world/${encodeURIComponent(n.id)}`;},onEdit:async(node,field,value)=>{const r=await repo.get('realities',node.id);if(!value.name||value.name.length>200)throw Error('Use a name of 1–200 characters.');await repo.put('realities',{...r,name:value.name,description:value.description,updatedAt:new Date().toISOString()});},onPosition:async(id,pos)=>{if(id==='create')return;const r=await repo.get('realities',id);await repo.put('realities',{...r,overviewX:pos.x,overviewY:pos.y});}});}
