function addNode(source=null,pos){const returnToCanvas=view!=='canvas';const available=Object.entries(TYPES).filter(([type])=>!sectionFor(type));if(!available.length){notify('All sections are already available.');return;}const count=sections().length,position=pos||{x:650+(count%3)*340,y:180+Math.floor(count/3)*220};modal('Add section',`<label>Section<select name="type">${available.map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label><label>Name <span>(optional)</span><input name="name" maxlength="200" placeholder="Use the section name"></label>`,async f=>{const d=await repo.createSection(reality.id,f.get('type'),{name:f.get('name'),...position});if(source&&source!==`root:${reality.id}`)await repo.connect(reality.id,source,d.id);await refresh();if(returnToCanvas)navigate('canvas');else paintCanvas();});}

function paintCanvas(){view='canvas';current=null;const rootId=`root:${reality.id}`;const manuscriptId=`manuscript:${reality.id}`;const visible=sections();const nodes=[{id:manuscriptId,name:'World Manuscript',type:'manuscript',subtitle:'COMPLETE WORLD',text:'Read and export all your writing.',editable:false,connectable:false,x:manuscriptPosition?.x??(reality.x??300),y:manuscriptPosition?.y??((reality.y??180)+240)},{id:rootId,name:reality.name,type:'world',subtitle:'ALTERNATIVE REALITY',text:reality.description||'',editable:true,updatedAt:reality.updatedAt,x:reality.x||300,y:reality.y||180},...visible.map(d=>({id:d.id,entryId:d.id,name:d.name,type:d.kind==='section'?'category':'note',subtitle:d.kind==='section'?`${TYPES[d.type].toUpperCase()} SECTION`:TYPES[d.type].toUpperCase(),text:d.description||'',editable:true,updatedAt:d.updatedAt,x:d.x,y:d.y}))];const nodeIds=new Set(nodes.map(n=>n.id));shell(`<div id="story-canvas" class="full-canvas"></div>`,'canvas');canvas=window.DaydreamNodeCanvas.mount(area.querySelector('#story-canvas'),`reality-${reality.id}`,{nodes,edges:[...edges.filter(e=>nodeIds.has(e.source)&&nodeIds.has(e.target)),{id:`manuscript-edge:${reality.id}`,source:rootId,target:manuscriptId,kind:'membership'}]},{label:`${reality.name} node map`,initialZoom:.9,canConnect:true,onPosition:async(id,p)=>{if(id===manuscriptId){manuscriptPosition={id:`manuscript-position:${reality.id}`,...p};await repo.put('settings',manuscriptPosition);return;}await repo.moveNode(id,p);const d=items.find(d=>d.id===id);if(d)Object.assign(d,p);else Object.assign(reality,p);},onEdit:async(node,field,value)=>{if(!value.name||value.name.length>200)throw Error('Use a name of 1–200 characters.');const details={name:value.name,description:value.description};if(node.id===rootId){const r=await repo.get('realities',reality.id);reality={...r,...details,updatedAt:new Date().toISOString()};await repo.put('realities',reality);}else{const d=await repo.get('documents',node.id);await repo.saveDocument({...d,...details});}await refresh();const header=area.querySelector('.reality-label');if(header)header.textContent=reality.name;const side=area.querySelector('.writer-sidebar'),tmp=document.createElement('div');tmp.innerHTML=sidebar();side?.replaceWith(tmp.firstElementChild);},onOpen:n=>{if(n.id===manuscriptId){navigate('manuscript');return;}if(n.id===rootId)navigate('library');else navigate('library',n.id);},onConnect:async(a,b)=>{if(a===manuscriptId||b===manuscriptId){notify('The manuscript includes every section automatically.');return;}await repo.connect(reality.id,a,b);await refresh();paintCanvas();},onCreate:addNode,onMenu:node=>nodeMenu(node),onDelete:node=>{if(node.id!==rootId&&node.id!==manuscriptId)deleteDocument(node.id);},onEdge:id=>{if(id===`manuscript-edge:${reality.id}`)return;const membership=edges.find(e=>e.id===id)?.kind==='membership';modal('Remove this connection?',membership?'<p>The section and its entries will stay available.</p>':'<p>Both nodes and their documents will stay.</p>',async()=>{await repo.disconnect(id);await refresh();paintCanvas();});}});}
async function openManuscript(){view='manuscript';current=null;group=null;window.DaydreamNodeCanvas.dispose();manuscriptData=await window.DaydreamManuscript.collect(reality);shell(`<section class="writing-view manuscript-view"><div class="document-tools"><button data-work="canvas">Back to canvas</button><span>World Manuscript</span><button data-work="export-manuscript" ${manuscriptData.documents.length?'':'disabled'}>Export PDF / JPG</button></div><div class="document-scroll"><article class="document-paper manuscript-paper"><h1>${esc(reality.name)}</h1>${reality.description?`<p class="manuscript-intro">${esc(reality.description).replace(/\n/g,'<br>')}</p>`:''}${manuscriptData.documents.length?window.DaydreamManuscript.html(manuscriptData):'<div class="manuscript-empty"><h2>No writing yet.</h2><p>Add entries in your sections. They will appear here automatically.</p></div>'}</article></div></section>`,'manuscript');const body=area.querySelector('.manuscript-paper');body.querySelectorAll('a[data-document]').forEach(a=>{const target=document.getElementById(`manuscript-${a.dataset.document}`);if(target)a.href=`#manuscript-${a.dataset.document}`;else{a.removeAttribute('data-document');a.classList.add('broken-link');a.title='Linked document is unavailable';}});document.title=`World Manuscript — ${reality.name}`;}
function nodeMenu(node){if(node.type==='manuscript'){navigate('manuscript');return;}const isRoot=node.id===`root:${reality.id}`;modal(isRoot?'Alternative reality':'Node actions',`<label>Action<select name="action"><option value="rename">Rename</option>${isRoot?'':`<option value="open">Open section</option><option value="delete">Remove section from canvas</option>`}</select></label><label>Name<input name="name" maxlength="200" value="${esc(node.name)}"></label>`,async f=>{const a=f.get('action');if(a==='rename'){const name=f.get('name').trim();if(!name)throw Error('Enter a name.');if(isRoot){reality={...reality,name};await repo.put('realities',reality);}else{const d=await repo.get('documents',node.id);await repo.saveDocument({...d,name});}await refresh();paintCanvas();}else if(a==='open')navigate('library',node.id);else if(a==='delete'){if(!confirm('Remove this section from the canvas? Its entries will stay in the document library. You can undo.'))return;undoId=await repo.removeDocument(node.id);await repo.put('settings',{id:'last-deletion',key:undoId,realityId:reality.id});await refresh();paintCanvas();}});}
function createEntry(){const section=items.find(d=>d.id===group);const parent=section?.canvasType?section:sectionFor(section?.type);if(!parent){notify('Choose a section from the sidebar first.');return;}navigate('new',parent.id);}
async function openBlank(parentId){const parent=items.find(d=>d.id===parentId);if(!parent?.canvasType)throw Error('Choose a section to add an entry.');const type=parent.type,now=new Date().toISOString();await openDocument({id:`draft-${window.DaydreamId.create()}`,isDraft:true,realityId:reality.id,name:'',type,kind:'document',number:null,parentId:parent.id,html:'<p><br></p>',x:0,y:0,createdAt:now,updatedAt:now});dirty=true;epoch++;notify('New document · will save when you return');}
function filtered(){const section=items.find(d=>d.id===group);let list=items.filter(d=>!d.canvasType||d.searchText.trim());if(section)list=list.filter(d=>d.type===section.type);if(typeFilter)list=list.filter(d=>d.type===typeFilter);if(pinnedOnly)list=list.filter(d=>d.pinned);const q=query.trim().toLowerCase();if(q)list=list.filter(d=>d.name.toLowerCase().includes(q)||d.searchText.includes(q)||String(d.number||'')===q);return list.sort((a,b)=>(a.number??Infinity)-(b.number??Infinity)||a.createdAt.localeCompare(b.createdAt));}

function library(){view='library';current=null;window.DaydreamNodeCanvas.dispose();const section=items.find(d=>d.id===group);shell(`<section class="document-scroll library-view"><div class="library-heading"><p class="eyebrow">${section?esc(TYPES[section.type]):'YOUR REALITY'}</p><h1>${esc(section?.name||(group==='unassigned'?'Unassigned documents':'Document library'))}</h1>${section?`<div class="library-buttons"><button data-work="add-in-section" class="light-button">+ Add ${esc(TYPES[section.type].toLowerCase())}</button></div>`:''}</div><div class="library-search"><label>${repo.isAccount?'Search titles, excerpts, or chapter number':'Search titles, writing, or chapter number'}<input id="library-query" type="search" value="${esc(query)}" placeholder="Find a character, a phrase, chapter 247…"></label><label>Type<select id="library-type"><option value="">All types</option>${Object.entries(TYPES).filter(([k])=>!section||k===section.type).map(([k,v])=>`<option value="${k}" ${typeFilter===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="inline-check"><input id="pinned-filter" type="checkbox" ${pinnedOnly?'checked':''}>Pinned only</label></div><div class="library-selection"><span id="library-count"></span></div><div id="library-entries"></div><div class="pagination"><button data-work="page-prev">Previous</button><span id="page-status"></span><button data-work="page-next">Next</button></div></section>`,'library');paintEntries();}
function paintEntries(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/40));page=Math.min(page,pages-1);area.querySelector('#library-count').textContent=`${list.length} entries`;area.querySelector('#library-entries').innerHTML=list.slice(page*40,page*40+40).map(d=>`<article class="library-entry"><button data-open="${esc(d.id)}" data-edit-section><span class="entry-type">${esc(TYPES[d.type])}${d.canvasType?' · section notes':''}${d.number?' · '+d.number:''}</span><strong>${esc(d.name)}</strong><p>${esc(d.excerpt||d.searchText.slice(0,110))||'Open to write'}</p></button><button data-pin="${esc(d.id)}" aria-label="${d.pinned?'Unpin':'Pin'} ${esc(d.name)}" aria-pressed="${!!d.pinned}">${d.pinned?'★':'☆'}</button></article>`).join('')||`<div class="library-empty"><h2>No entries here yet.</h2><p>${group?'Add your first entry, or try a different search.':'Open a section to start writing.'}</p></div>`;area.querySelector('#page-status').textContent=`Page ${page+1} of ${pages}`;area.querySelector('[data-work=page-prev]').disabled=page===0;area.querySelector('[data-work=page-next]').disabled=page>=pages-1;}
async function openDocument(input){const d=typeof input==='object'?input:await repo.get('documents',input),id=d?.id;if(!d)throw Error('This document is unavailable. Its links can be removed or replaced.');linkRange=null;current=d;current.lastOpened=new Date().toISOString();if(!d.isDraft&&!repo.isAccount)await repo.batch([{table:'documents',value:current},{table:'catalog',value:window.DaydreamDB.metadata(current)}]);const mi=items.findIndex(m=>m.id===id);if(mi>=0)items[mi]=window.DaydreamDB.metadata(current);view='doc';window.DaydreamNodeCanvas.dispose();const incoming=[];for(const m of items){if(m.id===id)continue; // Content is fetched only for backlinks on request.
 if(m.linkTargets?.includes(id))incoming.push(m);}
const chapters=items.filter(x=>x.type==='chapter'&&x.kind==='document').sort((a,b)=>(a.number??Infinity)-(b.number??Infinity)||a.createdAt.localeCompare(b.createdAt)),idx=chapters.findIndex(x=>x.id===id);
shell(`<section class="writing-view"><div class="document-tools"><button data-work="back">Back</button><span>${esc(TYPES[d.type])}${d.canvasType?' · section notes':''}</span><button class="touch-format-menu" data-work="writing-menu" aria-label="Open text formatting menu">⋯</button><button data-work="export">Export PDF / JPG</button><button data-work="delete">${d.canvasType?'Delete writing':'Delete'}</button>${d.type==='chapter'&&!d.canvasType?`<label class="chapter-number-label">Number<input id="chapter-number" aria-label="Chapter number" type="number" min="1" step="1" placeholder="Optional" value="${d.number||''}"></label>`:''}<button data-work="save" class="light-button">Save</button></div>${window.DaydreamFormat.toolbar()}<div class="document-scroll"><article class="document-paper"><input id="document-title" aria-label="Document title" maxlength="200" placeholder="Untitled ${esc(TYPES[d.type])}" value="${esc(d.name)}"><div id="document-body" contenteditable="true" role="textbox" aria-label="Document writing" aria-multiline="true" dir="auto"></div></article><section class="document-relations"><button data-work="backlinks">Show linked-from documents</button><div id="backlink-list"></div></section>${idx>=0?`<div class="chapter-navigation">${idx>0?`<button data-open="${esc(chapters[idx-1].id)}">Previous chapter</button>`:'<span></span>'}${idx<chapters.length-1?`<button data-open="${esc(chapters[idx+1].id)}">Next chapter</button>`:''}</div>`:''}</div></section>`,'doc');const body=area.querySelector('#document-body');body.innerHTML=sanitize(d.html);formatter=window.DaydreamFormat.mount(body,area,changed);body.querySelectorAll('a[data-document]').forEach(a=>{a.href=url('doc',a.dataset.document);if(!items.some(m=>m.id===a.dataset.document)){a.classList.add('broken-link');a.setAttribute('title','Linked document is unavailable');}});const remembered=positions.get(id);body.focus({preventScroll:true});if(remembered?.caret!=null){const walker=document.createTreeWalker(body,NodeFilter.SHOW_TEXT);let remaining=remembered.caret,node;while((node=walker.nextNode())){if(remaining<=node.textContent.length){const range=document.createRange();range.setStart(node,remaining);range.collapse(true);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);break;}remaining-=node.textContent.length;}}area.querySelector('.document-scroll').scrollTop=remembered?.scroll||0;if(window.matchMedia?.('(max-width:760px)').matches)area.querySelector('.format-panel').open=false;formatter.remember();formatter.sync();document.title=`${d.name||'Untitled '+TYPES[d.type]} — ${reality.name}`;if(d.isDraft)notify('New document · not saved yet');}
async function render(){if(window.DaydreamAuth&&!window.DaydreamAuth.user){window.DaydreamAuth.require(location.hash);return;}window.DaydreamFormat.dispose();const token=++routeToken;try{await repo.open();if(token!==routeToken)return;const parts=location.hash.slice(1).split('/').map(decodeURIComponent);if(parts[0]!=='world'){await overview();return;}const priorReality=reality?.id;reality=await repo.get('realities',parts[1]);if(priorReality!==reality?.id){group=null;query='';typeFilter='';pinnedOnly=false;}if(!reality)throw Error('This alternative reality was not found in the current workspace.');const [,last]=await Promise.all([refresh(),repo.get('settings','last-deletion')]);undoId=last?.realityId===reality.id&&await repo.get('trash',last.key)?last.key:null;if(token!==routeToken)return;activeHash=location.hash;const mode=parts[2]||'canvas',id=parts[3];if(mode==='manuscript')await openManuscript();else if(mode==='doc')await openDocument(id);else if(mode==='new')await openBlank(id);else if(mode==='library'){const nextGroup=id||null;if(group!==nextGroup){query='';typeFilter='';pinnedOnly=false;}group=nextGroup;page=0;library();}else paintCanvas();}catch(error){area.innerHTML=`<div class="workspace-unavailable"><h1>Workspace unavailable</h1><p role="alert">${esc(error.message)}</p><p>Your original saved data has not been removed.</p><button id="workspace-retry">Retry</button><a href="#workspace">Return to realities</a></div>`;area.querySelector('#workspace-retry').onclick=render;}}
async function deleteDocument(id){if(!await flush())return;const d=await repo.get('documents',id);if(!d)throw Error('This entry is unavailable.');if(d.canvasType&&view==='doc'){modal('Delete this section writing?',`<p>The ${esc(d.name)} section and its entries stay available. You can undo.</p>`,async()=>{const key=window.DaydreamId.create();await repo.batch([{table:'trash',value:{id:key,document:d,children:[],edges:[],deletedAt:new Date().toISOString()}},{table:'documents',value:{...d,html:'<p><br></p>'}},{table:'catalog',value:window.DaydreamDB.metadata({...d,html:'<p><br></p>'})},{table:'settings',value:{id:'last-deletion',key,realityId:reality.id}}]);undoId=key;dirty=false;current=null;await refresh();navigate('library',d.id);});return;}modal(d.canvasType?'Remove section from canvas?':'Delete this document?',`<p><strong>${esc(d.name)}</strong>${d.canvasType?' will leave the canvas. Its entries and any section writing stay in the document library.':' and its writing will be deleted.'} You can undo this action.</p>`,async()=>{undoId=await repo.removeDocument(id);await repo.put('settings',{id:'last-deletion',key:undoId,realityId:reality.id});dirty=false;current=null;await refresh();if(d.canvasType){navigate('canvas');if(location.hash===url('canvas'))paintCanvas();}else navigate('library',sectionFor(d.type)?.id||null);});}

function linkDialog(existing=null){if(!existing&&linkRange){const n=linkRange.commonAncestorContainer;existing=(n.nodeType===1?n:n.parentElement)?.closest('a[data-document]')||null;}if(existing){linkRange=document.createRange();linkRange.selectNodeContents(existing);}if(!linkRange||linkRange.collapsed||!area.querySelector('#document-body').contains(linkRange.commonAncestorContainer)){notify('Select the word or phrase you want to link first.');return;}const chosen=linkRange.cloneRange();modal('Create internal link','<label>Search documents<input name="search" placeholder="Ethan, a place, a chapter…"></label><label>Connect to<select name="destination" required></select></label>',async f=>{const id=f.get('destination');if(!items.some(d=>d.id===id))throw Error('Choose an existing document.');if(existing){existing.dataset.document=id;existing.href=url('doc',id);}else{const a=document.createElement('a');a.dataset.document=id;a.href=url('doc',id);a.append(chosen.extractContents());chosen.insertNode(a);}changed();});const select=dialog.querySelector('[name=destination]');function update(q=''){const list=items.filter(d=>(!d.canvasType||d.searchText.trim())&&d.id!==current.id&&d.name.toLowerCase().includes(q.toLowerCase())).slice(0,100),groups=new Map();for(const d of list){const parent=items.find(p=>p.id===d.parentId),key=parent?.name||TYPES[d.type];if(!groups.has(key))groups.set(key,[]);groups.get(key).push(d);}select.innerHTML=[...groups].map(([label,rows])=>`<optgroup label="${esc(label)}">${rows.map(d=>`<option value="${esc(d.id)}">${esc(d.name)} · ${esc(TYPES[d.type])}</option>`).join('')}</optgroup>`).join('');if(existing)select.value=existing.dataset.document;}update();dialog.querySelector('[name=search]').oninput=e=>update(e.target.value);}
const context=document.createElement('div');context.className='writing-context-menu';context.setAttribute('role','menu');context.hidden=true;document.body.append(context);function closeContext(){context.hidden=true;}area.addEventListener('contextmenu',e=>{const body=e.target.closest('#document-body');if(!body)return;const selected=getSelection();if(selected.rangeCount&&body.contains(selected.anchorNode)){linkRange=selected.getRangeAt(0).cloneRange();formatter.remember();}const existing=e.target.closest('a[data-document]');if(!linkRange)return;e.preventDefault();context.innerHTML=existing?'<button role="menuitem" data-link-menu="open">Open linked document</button><button role="menuitem" data-link-menu="change">Change destination</button><button role="menuitem" data-link-menu="remove">Remove link</button>':'<button role="menuitem" data-link-menu="create">Create internal link</button>';context.innerHTML+='<div class="context-divider"></div><button role="menuitem" data-context-format="bold">Bold</button><button role="menuitem" data-context-format="italic">Italic</button><button role="menuitem" data-context-format="underline">Underline</button><button role="menuitem" data-context-format="highlight">Highlight</button><button role="menuitem" data-context-format="heading">Heading</button><button role="menuitem" data-context-format="paragraph">Paragraph</button><button role="menuitem" data-context-format="list">List</button><button role="menuitem" data-context-format="clear">Clear formatting</button>';context.hidden=false;context.style.left=`${Math.max(8,Math.min(e.clientX,window.innerWidth-240))}px`;context.style.top=`${Math.max(8,Math.min(e.clientY,window.innerHeight-Math.min(480,window.innerHeight-16)))}px`;context.querySelectorAll('button').forEach(b=>b.onclick=()=>{closeContext();if(b.dataset.contextFormat){formatter?.format(b.dataset.contextFormat);return;}if(b.dataset.linkMenu==='create')linkDialog();if(b.dataset.linkMenu==='change')linkDialog(existing);if(b.dataset.linkMenu==='remove'){existing.replaceWith(...existing.childNodes);changed();}if(b.dataset.linkMenu==='open'){const target=items.find(d=>d.id===existing.dataset.document);if(target)navigate('doc',target.id);else notify('The linked document is unavailable.',true);}});context.querySelector('button').focus();});context.addEventListener('keydown',e=>{const buttons=[...context.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length].focus();}if(e.key==='Escape'){closeContext();formatter?.restore();}});document.addEventListener('pointerdown',e=>{if(!context.contains(e.target))closeContext();});
async function exportWork(ids){if(!await flush())return;await window.DaydreamDocumentExport.open({reality,ids});}
area.addEventListener('input',e=>{if(['document-body','document-title','chapter-number'].includes(e.target.id))changed();if(e.target.id==='library-query'){query=e.target.value;page=0;paintEntries();}});
area.addEventListener('change',async e=>{try{if(e.target.id==='library-type'){typeFilter=e.target.value;page=0;paintEntries();}if(e.target.id==='pinned-filter'){pinnedOnly=e.target.checked;page=0;paintEntries();}}catch(err){notify(err.message,true);}});

